/* Conteúdo das lições — português */
I18N.registerLessons("pt", {

/* ===================== PIANO ===================== */
"piano-1":{title:"Conhecendo as teclas",goal:"Identificar qualquer nota do piano em cinco segundos",b:{
0:"O piano assusta: 88 teclas. A verdade? Existem apenas <b>12 teclas</b> que se repetem sem parar. Assim que você enxergar o padrão, o instrumento inteiro se abre.",
1:"O segredo está nas teclas pretas: elas ficam em grupos de <b>duas</b> e de <b>três</b>, alternando. Esse é o seu mapa.",
2:["Encontre um grupo de duas teclas pretas.","A tecla branca logo à esquerda delas (no sentido dos graves) é o <b>dó (C)</b>.","Daí é só seguir: dó, ré, mi, fá, sol, lá, si — e dó de novo.","Cada dó seguinte é o mesmo som, só que mais agudo. Isso se chama <b>oitava</b>."],
3:"Pressione a tecla destacada — este é o dó (C4). Tente achar também os outros dós.",
4:"<b>Dica de ouro:</b> o dó central (C4) fica mais ou menos no meio do piano, em frente à fechadura ou ao logotipo. É o ponto de referência de todo pianista.",
5:"A escala de dó maior — as sete notas brancas e a volta ao dó",
6:{q:"Como se localiza a nota dó no piano?",o:["A tecla branca à esquerda de três pretas","A tecla branca colada ao grupo de duas pretas, do lado grave","A primeira tecla preta","A tecla branca no meio do teclado"],w:"O dó é sempre a tecla branca colada ao grupo de duas pretas, do lado dos sons graves."},
7:"Sente-se ao teclado (real ou o da tela) e diga em voz alta todos os dós, depois todos os fás. Três minutos e pronto."}},

"piano-2":{title:"A mão direita — cinco dedos, cinco notas",goal:"Tocar dó–ré–mi–fá–sol em sequência sem olhar as mãos",b:{
0:"No piano cada dedo tem um número: <b>1 = polegar</b>, 2 = indicador, 3 = médio, 4 = anelar, 5 = mínimo. A numeração é igual nas duas mãos.",
1:"Coloque o polegar direito no <b>dó (C4)</b> e cada dedo seguinte na próxima tecla branca. Agora seus cinco dedos estão exatamente sobre dó-ré-mi-fá-sol. É a «posição de dó» — a primeira posição que todo pianista aprende.",
2:"Posição de dó — dedos 1, 2, 3, 4, 5",
3:["Curve levemente os dedos, como se segurasse uma laranja pequena.","Mantenha o punho reto — nem afundado nem levantado.","Toque 1-2-3-4-5 devagar, cada nota com o mesmo volume.","Agora volte: 5-4-3-2-1.","Quando fluir, feche os olhos e toque de novo."],
4:"<b>Igualdade de som importa mais que velocidade.</b> O dedo fraco (o 4) sempre tentará tocar mais baixo. Dê atenção especial a ele.",
5:"Exercício de dedos nº 1",
6:{q:"Qual dedo é o número 1 no piano?",o:["O mínimo","O médio","O polegar","O indicador"],w:"O polegar é sempre o dedo número 1 — nas duas mãos."},
7:"Toque o exercício cinco vezes seguidas sem erro. Se errar, recomece mais devagar."}},

"piano-3":{title:"Sua primeira música",goal:"Tocar uma melodia completa de ouvido e lendo",b:{
0:"Chegou a hora: você está tocando uma música. «Brilha, brilha, estrelinha» é uma melodia folclórica francesa do século XVIII (domínio público) — Mozart até escreveu variações sobre ela.",
1:"Todas as notas estão na posição de dó que você aprendeu, exceto o <b>lá (A4)</b>, que alcançamos deslocando um pouco o dedo mínimo.",
2:"Brilha, brilha, estrelinha — a melodia completa",
3:"As notas necessárias para a música",
4:["Ouça a melodia duas vezes com o botão de reprodução.","Toque só as quatro primeiras notas: dó dó sol sol.","Acrescente: lá lá sol (o sol é longo — dois tempos).","Continue: fá fá mi mi ré ré dó.","Junte tudo devagar e só depois acrescente velocidade."],
5:"<b>A regra central do estudo autodidata:</b> devagar = rápido. Um cérebro que aprende devagar e sem erros chega à velocidade três vezes mais rápido.",
6:{q:"Em que andamento se deve começar uma música nova?",o:["O mais rápido possível","No andamento em que você toca sem erros","No andamento original da música","Não faz diferença"],w:"O andamento certo é aquele em que sai sem erros. A velocidade vem sozinha depois."},
7:"Toque a música três vezes seguidas sem parar."}},

"piano-4":{title:"Ritmo — a língua do tempo",goal:"Contar 1-2-3-4 e tocar diferentes figuras",b:{
0:"Música não é só quais notas — é <b>quando</b>. As figuras básicas:",
1:["<b>Semibreve</b> — dura 4 tempos.","<b>Mínima</b> — 2 tempos.","<b>Semínima</b> — um tempo. É a figura mais comum de todas.","<b>Colcheia</b> — meio tempo. Conta-se 1-e-2-e."],
2:"Exercício de ritmo — contando em quatro",
3:"A maioria das músicas populares tem <b>quatro tempos por compasso</b> (4/4). O primeiro tempo é mais forte — é o pulso da música.",
4:"Primeiro se bate palma, depois se toca. Se você não consegue bater um ritmo, também não vai conseguir tocá-lo.",
5:"A mesma nota, figuras diferentes",
6:{q:"Quantos tempos dura uma semínima em 4/4?",o:["4","2","1","Meio"],w:"Uma semínima = um tempo. Quatro semínimas preenchem um compasso completo."},
7:"Coloque o metrônomo em 70 e bata palmas exatamente nos tempos. Depois bata colcheias (duas vezes por tempo)."}},

"piano-5":{title:"A mão esquerda entra em cena",goal:"Tocar um baixo simples com a mão esquerda",b:{
0:"A mão esquerda toca os sons graves — a base harmônica. Vamos começar simples: uma nota por compasso.",
1:"Dó e sol na oitava da mão esquerda",
2:["Coloque o mínimo esquerdo no dó (C3).","Coloque o polegar no sol (G3).","Toque dó — conte 4. Toque sol — conte 4.","Quando estiver firme, toque dó-sol-dó-sol nos tempos 1 e 3."],
3:"A mão esquerda sempre parece «burra» no começo. É totalmente normal — ela apenas treinou menos na vida. Em uma semana ela alcança a outra.",
4:"Exercício de baixo",
5:{q:"Qual é a função principal da mão esquerda no piano popular?",o:["Tocar a melodia","Tocar o baixo e a harmonia","Virar as páginas","Só marcar o tempo"],w:"A mão esquerda constrói a base harmônica sobre a qual a melodia da direita se apoia."},
6:"Toque o exercício de baixo com o metrônomo em 70."}},

"piano-6":{title:"As duas mãos juntas — o grande momento",goal:"Coordenar as mãos num exercício simples",b:{
0:"É aqui que a maioria dos autodidatas trava, por um único motivo: juntam as mãos cedo demais.",
1:["Toque a mão direita sozinha até que fique totalmente automática.","Faça o mesmo com a esquerda.","Toque um único compasso com as duas mãos — e pare.","Acrescente um compasso de cada vez.","Se travar, volte às mãos separadas. Sempre."],
2:"Exercício a duas mãos (a melodia)",
3:"Exercício a duas mãos (o baixo)",
4:"<b>Um truque que funciona:</b> diga em voz alta as notas da mão direita enquanto toca. Isso obriga o cérebro a separar as mãos.",
5:{q:"O que fazer quando não se consegue juntar as duas mãos?",o:["Tocar mais rápido","Desistir da mão esquerda","Voltar às mãos separadas e juntar só um compasso","Mudar de música"],w:"Dividir em pedaços pequenos e reconstruir aos poucos é o único método que funciona."},
6:"Toque os dois exercícios juntos, só dois compassos, dez vezes."}},

"piano-7":{title:"Escala de dó maior e a passagem do polegar",goal:"Tocar uma oitava completa com uma mão",b:{
0:"Você só tem cinco dedos — e a escala tem oito notas. A solução é a <b>passagem do polegar</b>, o movimento mais importante da técnica pianística.",
1:"Escala de dó maior ascendente",
2:["Mão direita: 1-2-3 em dó-ré-mi.","Enquanto o dedo 3 toca mi, o polegar «passa» por baixo da palma.","O polegar pousa no fá — e dali 1-2-3-4-5 até o dó seguinte.","A dedilhação completa: 1 2 3 1 2 3 4 5.","Na descida: 5 4 3 2 1 3 2 1."],
3:"O cotovelo e o antebraço devem acompanhar levemente a mão para a direita. Se só o polegar se mexer, ficará desajeitado.",
4:"Escala de dó maior — ida e volta",
5:{q:"Quando o polegar passa por baixo da palma na escala de dó maior ascendente?",o:["Depois da nota ré","Enquanto o dedo 3 toca mi","Depois do sol","Ele não passa"],w:"A passagem acontece enquanto o dedo 3 toca mi, para que o polegar chegue a tempo ao fá."},
6:"Toque a escala ida e volta quatro vezes com o metrônomo em 60."}},

"piano-8":{title:"Acordes — três notas que mudam tudo",goal:"Tocar C, F e G com a mão esquerda",b:{
0:"Um <b>acorde</b> são três ou mais notas soando juntas. Um acorde maior se constrói pulando: nota, pula uma, nota, pula uma, nota.",
1:"Acorde de dó maior (C) — dó-mi-sol",
2:"Acorde de fá maior (F) — fá-lá-dó",
3:"Acorde de sol maior (G) — sol-si-ré",
4:"Esses três acordes (C, F, G) bastam para centenas de músicas. São «os três grandes» da tonalidade.",
5:"Repare que os três se constroem igual: dedos 5-3-1 da mão esquerda, sobre tecla branca, pula, tecla, pula, tecla.",
6:{q:"De quais notas é formado o acorde de dó maior?",o:["dó-ré-mi","dó-mi-sol","dó-fá-lá","dó-sol-dó"],w:"Um acorde maior é formado pelos graus 1º, 3º e 5º da escala: dó-mi-sol."},
7:"Alterne entre C, F e G, quatro tempos por acorde, com o metrônomo em 60."}},

"piano-9":{title:"Acompanhamento — tocar uma música com acordes",goal:"Combinar melodia na direita com acordes na esquerda",b:{
0:"Agora juntamos: a mão esquerda toca um acorde e a direita a melodia. É assim que se acompanha qualquer música do mundo.",
1:["Toque «Brilha, brilha, estrelinha» com a mão direita.","No primeiro compasso — acorde C na mão esquerda.","Quando a melodia chegar a «lá lá sol» — vá para F e depois para C.","No penúltimo compasso — G, e para terminar C de novo."],
2:"Melodia para praticar",
3:"<b>Como saber qual acorde combina?</b> Veja qual acorde contém a nota que a melodia toca naquele tempo. Se a melodia toca mi, C serve (dó-mi-sol).",
4:{q:"Qual acorde contém a nota lá?",o:["C (dó-mi-sol)","G (sol-si-ré)","F (fá-lá-dó)","Nenhum"],w:"O acorde F é formado por fá-lá-dó, portanto contém a nota lá."},
5:"Toque a música com acompanhamento, bem devagar, duas vezes."}},

"piano-10":{title:"Maior e menor — a cor emocional",goal:"Reconhecer e tocar acordes menores",b:{
0:"A diferença entre «alegre» e «triste» na música é <b>um semitom</b>. Mova a nota do meio de um acorde maior uma tecla para a esquerda e você terá um acorde menor.",
1:"Acorde de lá menor (Am) — lá-dó-mi",
2:"Acorde de ré menor (Dm) — ré-fá-lá",
3:"Acorde de mi menor (Em) — mi-sol-si",
4:"Toque C e depois Am, um atrás do outro. Repare como o clima do som muda na hora. Esse é o poder da harmonia.",
5:{q:"Qual é a diferença entre um acorde maior e um menor?",o:["O menor é mais agudo","A nota do meio do menor é um semitom mais grave","O menor tem quatro notas","Não há diferença real"],w:"A nota do meio (a terça) desce um semitom — e nisso está toda a diferença entre «alegre» e «triste»."},
6:"Toque a sequência C – Am – F – G, quatro tempos por acorde. É a sequência mais comum da música popular."}},

"piano-11":{title:"Dinâmica, pedal e expressão",goal:"Transformar um toque técnico em musical",b:{
0:"Duas pessoas tocarão as mesmas notas — e uma soará como um robô. A diferença é a <b>dinâmica</b>: a variação de volume ao tocar.",
1:["<b>Piano (p)</b> — fraco. <b>Forte (f)</b> — forte.","<b>Crescendo</b> — aumento gradual. <b>Diminuendo</b> — diminuição gradual.","Toque a escala: comece fraco, chegue ao ápice no dó agudo e diminua na descida.","Uma frase musical é como uma frase falada — tem começo, ápice e fim."],
2:"<b>O pedal direito</b> (de sustentação) levanta os abafadores das cordas — e o som continua soando. A regra: trocar o pedal a cada mudança de acorde, senão vira uma «lama» sonora.",
3:"A técnica certa: o pedal é pisado <b>logo depois</b> de o dedo tocar, não antes. Chama-se «pedal atrasado».",
4:{q:"Quando se troca o pedal?",o:["A cada nota","A cada mudança de acorde","Só no fim da peça","Nunca, mantém-se pisado"],w:"Trocar o pedal a cada mudança de acorde mantém o som limpo."},
5:"Toque a escala com crescendo na subida e diminuendo na descida."}},

"piano-12":{title:"Peça final — Hino à Alegria",goal:"Tocar uma obra clássica completa",b:{
0:"Você terminou o percurso básico. É hora de tocar uma obra de verdade: o tema da Nona sinfonia de Beethoven (1824) — domínio público.",
1:"Hino à Alegria",
2:["Toque a mão direita sozinha, de quatro em quatro compassos.","Acrescente um baixo simples na esquerda: C – C – G – C.","Acrescente dinâmica: começo calmo, ápice no meio.","Acrescente pedal nas mudanças de acorde.","Toque do começo ao fim sem parar — mesmo que erre."],
3:"<b>A regra do músico experiente:</b> na execução não se para para corrigir. Segue-se em frente. As correções pertencem ao estudo, não à execução.",
4:{q:"Qual é a forma mais eficaz de estudar uma peça nova?",o:["Tocá-la inteira várias vezes","Isolar os trechos difíceis e trabalhar só neles","Tocar só as partes fáceis","Só ouvir gravações"],w:"O trabalho focado nos trechos difíceis economiza horas. 80 % do tempo deve ir para os 20 % mais difíceis."},
5:"Grave-se tocando (com o celular) e escute. Você vai ouvir coisas que não percebeu enquanto tocava."}},

/* ===================== VIOLÃO ===================== */
"guitar-1":{title:"Conhecendo o violão e a postura correta",goal:"Sentar bem, segurar bem e afinar o violão",b:{
0:"O violão tem seis cordas. A mais grossa (em cima) é o <b>mi grave (E)</b> e a mais fina (embaixo) o <b>mi agudo (E)</b>. A numeração vai <b>da fina para a grossa</b>: a mais fina é a corda 1.",
1:["Corda 6 — mi grave (E2)","Corda 5 — lá (A2)","Corda 4 — ré (D3)","Corda 3 — sol (G3)","Corda 2 — si (B3)","Corda 1 — mi agudo (E4)"],
2:"O som das cordas soltas — da grossa para a fina",
3:"<b>Sentar corretamente:</b> coluna reta, corpo do violão sobre a perna direita (para destros), braço levemente elevado. Polegar da mão esquerda atrás do braço — sem aparecer por cima.",
4:"Dor nas pontas dos dedos nas duas primeiras semanas é normal — a pele endurece. Dor no punho ou no ombro <b>não</b> é normal e indica postura errada. Pare e ajuste a posição.",
5:"Afine o violão antes de cada estudo. Um violão desafinado ensina sons errados ao seu ouvido. Use o <a href='#/tools/tuner'>afinador do aplicativo</a>.",
6:{q:"Qual corda é a número 1?",o:["A mais grossa","A mais fina","A do meio","Depende do violão"],w:"A corda 1 é a mais fina — o mi agudo."},
7:"Afine o violão e depois toque cada corda solta dizendo o nome dela em voz alta."}},

"guitar-2":{title:"A mão direita — sua primeira batida",goal:"Produzir um som limpo e uniforme nas cordas soltas",b:{
0:"A mão direita é responsável pelo som e pelo ritmo. Dá para tocar com palheta ou com os dedos — vamos começar com palheta.",
1:["Segure a palheta entre o polegar e o indicador, deixando só 3–5 mm para fora.","O movimento vem do punho, não do cotovelo.","Passe para baixo por todas as seis cordas — um som contínuo.","Agora para cima, da corda fina para a grossa.","Pratique: baixo, baixo, baixo, baixo — em andamento uniforme."],
2:"Batidas em semínimas — quatro tempos",
3:"Se o som «tropeça», provavelmente você está apertando demais a palheta. Uma pegada relaxada dá um som liso.",
4:{q:"De onde deve vir o movimento da batida?",o:["Do ombro","Do cotovelo","Do punho","Só dos dedos"],w:"O movimento de punho é relaxado, rápido e não causa lesões."},
5:"Toque cordas soltas por 2 minutos seguidos com o metrônomo em 70. Olho na uniformidade do som."}},

"guitar-3":{title:"O primeiro acorde — Em",goal:"Fazer um acorde limpo e batê-lo no tempo",b:{
0:"Em (mi menor) é o acorde mais fácil do mundo: só dois dedos, e as seis cordas são tocadas.",
1:null,
2:["Dedo 2 na casa 2 da corda 5 (lá).","Dedo 3 na casa 2 da corda 4 (ré).","Pressione perto do traste — nem em cima dele nem no meio.","Os dedos ficam na ponta, não deitados.","Toque corda por corda e verifique se cada uma soa limpa."],
3:"Som «morto» ou trastejando? Quase sempre a causa é um dedo deitado encostando numa corda vizinha. Levante a palma e curve mais os dedos.",
4:"O método de verificação dos professores: toque cada corda separadamente (um «arpejo»). A corda que não soa mostra exatamente qual dedo corrigir.",
5:{q:"O que fazer quando uma corda do acorde trasteja?",o:["Apertar mais com todos os dedos","Verificar qual dedo está deitado encostando numa corda vizinha","Reafinar o violão","Trocar as cordas"],w:"Em 90 % dos casos um dedo vizinho encosta na corda. A solução é curvar os dedos, não fazer força."},
6:"Segure Em e bata 16 tempos seguidos. Solte, sacuda a mão e repita — cinco vezes."}},

"guitar-4":{title:"Um segundo acorde e a primeira troca",goal:"Passar de Em para Am sem parar",b:{
0:"Am (lá menor) é exatamente a mesma forma de Em — apenas deslocada uma corda, com um dedo a mais.",
1:null,
2:["Pegue a forma de Em e desloque-a uma corda no sentido das cordas finas.","Acrescente o dedo 1 na casa 1 da corda 2 (si).","Não toque a corda 6.","Passe Em → Am → Em → Am, sem bater — só a mão."],
3:"<b>O segredo das trocas:</b> pratique a passagem <u>sem bater</u>, 20 vezes. O cérebro aprende o movimento sem a pressão do som. Depois acrescente a batida.",
4:"<b>Dedo âncora:</b> entre Em e Am dois dedos mantêm a mesma forma. Não levante a mão toda — deslize-a.",
5:{q:"Qual é a forma mais eficaz de praticar uma troca de acorde?",o:["Tocar a música rápido várias vezes","Praticar só o movimento da mão, sem bater","Praticar cada acorde separado","Praticar só com metrônomo rápido"],w:"Separar o movimento da mão da batida faz o cérebro aprender o gesto limpo e rápido."},
6:"60 trocas Em↔Am. Conte em voz alta. Quatro minutos que mudam tudo."}},

"guitar-5":{title:"A batida de acompanhamento — para baixo e para cima",goal:"Tocar a batida de acompanhamento mais comum do mundo",b:{
0:"A batida mais básica: <b>baixo, baixo-cima, cima-baixo-cima</b>. Se você aprender só uma batida na vida, que seja esta.",
1:["Conte em voz alta: 1 e 2 e 3 e 4 e.","A mão sobe e desce o tempo todo — como um pêndulo, sem parar.","Nos tempos em que não se toca, a mão continua se movendo no ar, apenas não encosta.","O padrão: ↓ . ↓↑ . ↑↓↑ (1, 2-e, 3-e-4-e)."],
2:"A batida de acompanhamento básica",
3:"A mão que não para é o segredo. Iniciantes param a mão — e perdem o ritmo. Deixe-a sempre em movimento.",
4:{q:"Por que a mão direita deve continuar se movendo mesmo sem bater?",o:["Para ficar bonito","Para manter a sensação contínua do ritmo","Para a mão não cansar","Não é importante"],w:"O movimento contínuo é o seu relógio interno. Parar quebra o ritmo."},
5:"Toque Em com essa batida por um minuto inteiro sem parar, depois Am."}},

"guitar-6":{title:"O acorde de C — e uma troca mais difícil",goal:"Fazer um C limpo e usá-lo numa sequência",b:{
0:"C (dó maior) exige três dedos em três casas diferentes. É o acorde que separa quem persiste de quem desiste.",
1:null,
2:["Dedo 1 — casa 1, corda 2.","Dedo 2 — casa 2, corda 4.","Dedo 3 — casa 3, corda 5.","Não toque a corda 6.","Confirme que as cordas soltas 1 e 3 soam livres."],
3:"Se a corda 1 (a fina) não soa, é o seu dedo 1 deitado sobre ela. Gire um pouco o punho para a frente.",
4:{q:"Quais cordas não são tocadas num acorde de C aberto?",o:["A corda 1","A corda 6","As cordas 5 e 6","Todas são tocadas"],w:"No acorde de C começa-se pela quinta corda. A sexta não faz parte do acorde."},
5:"Pratique C → Am → C → Am, quatro tempos cada."}},

"guitar-7":{title:"G e D — sua primeira música de três acordes",goal:"Tocar uma música completa com G, C e D",b:{
0:"Com G, C e D dá para tocar milhares de músicas. É a «família de sol» — os três acordes centrais da tonalidade de sol maior.",
1:null,2:null,
3:"<b>A estrutura clássica:</b> G – G – C – C – G – G – D – C – G. Quatro tempos por acorde.",
4:"Batida de acompanhamento para a música",
5:"Repare que ao passar de G para C o dedo 3 pode ficar na mesma casa — é um «dedo âncora» que reduz a troca pela metade.",
6:{q:"O que os acordes G, C e D têm em comum?",o:["São todos menores","São os três acordes centrais da escala de sol maior","Estão na mesma casa","Usam os mesmos dedos"],w:"São os graus I, IV e V da escala de sol maior — o esqueleto harmônico da maioria das músicas."},
7:"Toque o ciclo G-C-G-D duas vezes sem parar, mesmo que as trocas sejam lentas."}},

"guitar-8":{title:"Trocas rápidas e dedos âncora",goal:"Encurtar o tempo de passagem entre acordes",b:{
0:"Trocas lentas são o problema número um dos violonistas iniciantes. A solução não é força nem velocidade — é <b>eficiência</b>.",
1:["<b>Dedo âncora:</b> identifique um dedo que fica parado entre dois acordes — não o levante.","<b>Movimento mínimo:</b> levante os dedos apenas 2 mm das cordas.","<b>Tempo certo:</b> troque de acorde no último tempo, não depois.","<b>O exercício do relógio:</b> marque um minuto e conte quantas trocas limpas conseguiu. Bata seu recorde todo dia."],
2:"Anote seu recorde de trocas no diário de estudo do aplicativo. Progresso mensurável é o motor mais forte da constância.",
3:{q:"O que é um «dedo âncora»?",o:["O polegar atrás do braço","Um dedo que fica parado ao passar entre dois acordes","O dedo mais forte","Um dedo que pressiona duas cordas"],w:"Um dedo âncora encurta a troca e serve de referência para os outros dedos."},
4:"Um minuto de trocas C↔G. Anote o número. Volte amanhã e supere-o."}},

"guitar-9":{title:"Batidas — variando o acompanhamento",goal:"Conhecer três batidas diferentes",b:{
0:"Os mesmos acordes com outra batida soam como uma música completamente diferente. Aqui vão três batidas que cobrem quase qualquer estilo.",
1:"Batida 1 — balada lenta",
2:"Batida 2 — pop padrão",
3:"Batida 3 — acento contratempo",
4:"<b>A batida de contratempo</b> — tocar só nos «e» entre os tempos — dá uma sensação saltitante e combina com reggae, ska e muitos estilos folk.",
5:{q:"O que muda quando se tocam os mesmos acordes com outra batida?",o:["A harmonia","O caráter e o estilo da música","A altura dos sons","Só a velocidade"],w:"A batida é o que define o estilo. Os mesmos quatro acordes podem soar como balada, rock ou reggae."},
6:"Toque a mesma sequência de acordes com as três batidas."}},

"guitar-10":{title:"Seu primeiro solo — a escala pentatônica",goal:"Improvisar um solo curto sobre cinco notas",b:{
0:"A escala pentatônica (cinco notas) é o segredo de todo solista de rock e blues. A mágica dela: é quase impossível tocar uma nota «errada».",
1:"Pentatônica menor de lá — ascendente",
2:["Coloque o dedo 1 na casa 5, corda 6 (lá).","O desenho: 5-8 nas cordas 6 e 5, 5-7 nas cordas 4 e 3, 5-8 nas cordas 2 e 1.","Toque o desenho subindo e descendo até os dedos memorizarem.","Agora esqueça a ordem — toque as notas aleatoriamente. Isso é improvisar."],
3:"Um bom solo não é muita nota — são notas com <b>silêncios</b> entre elas. Deixe espaço para respirar.",
4:{q:"Por que é fácil improvisar com a escala pentatônica?",o:["Ela só tem notas agudas","Ela contém 5 notas que combinam todas harmonicamente","Só se pode tocá-la numa corda","Ela é tocada devagar"],w:"As notas «que se chocam» foram tiradas da escala — por isso qualquer combinação soa bem."},
5:"Improvise 8 compassos na pentatônica sobre um metrônomo."}},

"guitar-11":{title:"Famílias de acordes — A, E, Dm",goal:"Ampliar seu repertório de acordes para oito",b:{
0:null,1:null,2:null,
3:"Com os oito acordes aprendidos (Em, Am, C, G, D, A, E, Dm) você pode tocar a grande maioria das músicas populares.",
4:"<b>A regra de combinação:</b> acordes da mesma «família» (tonalidade) soam bem juntos. Família de dó: C, Dm, Em, F, G, Am. Família de sol: G, Am, Bm, C, D, Em.",
5:{q:"Qual acorde não pertence à família de sol maior?",o:["C","D","Em","F"],w:"F não faz parte da escala de sol maior (que tem fá sustenido). Ele pertence à família de dó."},
6:"Escolha quatro acordes de uma mesma família e toque-os em ciclo."}},

"guitar-12":{title:"Peça final e um olhar adiante — a pestana",goal:"Tocar uma música completa e conhecer a próxima etapa",b:{
0:"Você terminou o percurso básico. Sabe afinar, bater, tocar oito acordes, três batidas e um solo.",
1:"Melodia de encerramento — Amazing Grace (domínio público)",
2:"<b>A próxima etapa: o acorde com pestana.</b> O dedo 1 se deita sobre todas as cordas e imita um capotraste. Isso abre o braço inteiro.",
3:["Apoie o dedo 1 esticado sobre as seis cordas na casa 1.","Use o lado externo do dedo, não a polpa mole.","Acrescente a forma de E com os dedos 2, 3 e 4 — e você tem um F.","Não desanime: uma pestana limpa leva de 2 a 4 semanas para a maioria."],
4:"Se sentir dor no punho ao fazer pestana — pare. O problema é o ângulo do polegar, não falta de força. Pratique na casa 5, onde as cordas são mais macias.",
5:{q:"O que é um acorde com pestana?",o:["Um acorde só com cordas soltas","Um acorde em que um dedo pressiona várias cordas ao mesmo tempo","Um acorde de quatro notas","Um acorde rápido"],w:"O dedo 1 cria uma «pestana móvel», permitindo deslocar formas de acorde por todo o braço."},
6:"Toque uma música completa da biblioteca com acompanhamento e grave-se."}},

/* ===================== UKULELE ===================== */
"ukulele-1":{title:"Ukulele em 10 minutos",goal:"Tocar o primeiro acorde e batê-lo",b:{
0:"O ukulele é o instrumento mais rápido do mundo para começar: quatro cordas de náilon macias e afinação padrão <b>G-C-E-A</b>.",
1:"As cordas soltas",2:null,
3:["Segure o ukulele contra o corpo com o antebraço direito.","Coloque o dedo 3 na casa 3 da corda fina (lá).","Bata suavemente para baixo com a polpa do indicador.","Pronto — você tocou um acorde de dó."],
4:"No ukulele se bate onde o braço encontra o corpo — ali o som é mais cheio.",
5:{q:"Qual é a afinação padrão de um ukulele soprano?",o:["E-A-D-G","G-C-E-A","C-F-A-D","D-G-B-E"],w:"G-C-E-A é a afinação padrão, e o sol é na verdade mais agudo que o dó («afinação alta»)."},
6:"Bata o acorde de C por um minuto em andamento uniforme."}},

"ukulele-2":{title:"Dois acordes = uma música inteira",goal:"Passar de C para Am",b:{
0:null,
1:"Am também precisa de um único dedo — o dedo 2 na casa 2 da corda grossa (sol).",
2:"Batida simples — quatro para baixo",
3:"Toque quatro tempos de C, quatro de Am e repita. Isso já é uma forma de música legítima para cantar por cima.",
4:{q:"Quantos dedos são necessários para o acorde Am no ukulele?",o:["Um","Dois","Três","Quatro"],w:"Apenas um dedo, na casa 2 da corda grossa."},
5:"30 trocas C↔Am com metrônomo lento."}},

"ukulele-3":{title:"O terceiro acorde — F",goal:"Tocar uma sequência de três acordes",b:{
0:null,
1:"Com C, Am e F já dá para tocar centenas de músicas. A sequência C – Am – F – C é um clássico.",
2:"Batida pop",
3:{q:"Qual sequência comum usa esses três acordes?",o:["F – F – F – F","C – Am – F – C","C – C# – D","Só Am"],w:"C – Am – F é uma das sequências mais frequentes da música popular."},
4:"Toque a sequência C-Am-F-C quatro vezes seguidas."}},

"ukulele-4":{title:"Batidas e como variar",goal:"Três batidas de acompanhamento",b:{
0:"Batida das ilhas",1:"Valsa — três tempos",
2:"A batida «das ilhas» (baixo, baixo-cima, cima-baixo-cima) é o som clássico do ukulele.",
3:"Mantenha a mão direita totalmente relaxada. No ukulele, força é igual a som áspero.",
4:{q:"Quantos tempos tem um compasso de valsa?",o:["2","3","4","6"],w:"A valsa é 3/4 — três tempos por compasso, com acento no primeiro."},
5:"Toque a sequência aprendida com duas batidas diferentes."}},

"ukulele-5":{title:"G e Em — abrindo o repertório",goal:"Dominar cinco acordes",b:{
0:null,1:null,
2:"G exige três dedos em triângulo, e Em é uma diagonal descendente. Os dois precisam de prática lenta no começo.",
3:"Pratique a troca C→G sem bater, 20 vezes. Você vai notar a mão «aprendendo» a forma em minutos.",
4:{q:"O que mais ajuda a dominar uma troca de acorde nova?",o:["Tocar rápido","Praticar o movimento sem bater","Apertar mais","Trocar as cordas"],w:"Separar o movimento do som acelera a aprendizagem motora."},
5:"30 trocas C↔G e 30 trocas Am↔Em."}},

"ukulele-6":{title:"Dedilhado",goal:"Tocar um arpejo básico",b:{
0:"Em vez de bater todas as cordas juntas, vamos pinçá-las uma após a outra — isso se chama <b>arpejo</b> e combina com músicas calmas.",
1:["Polegar — corda 4 (sol).","Indicador — corda 3 (dó).","Médio — corda 2 (mi).","Anelar — corda 1 (lá).","Toque 4-3-2-1 e depois 1-2-3-4."],
2:"Arpejo no acorde de C",
3:{q:"O que é um arpejo?",o:["Uma batida forte","Tocar as notas de um acorde uma após a outra","Uma troca rápida de acorde","Um tipo de palheta"],w:"Arpejo = «acorde quebrado» — as notas são tocadas em sequência, não juntas."},
4:"Toque um arpejo em C, Am e F, quatro tempos cada."}},

"ukulele-7":{title:"Melodia no ukulele",goal:"Tocar melodia, não só acompanhamento",b:{
0:"O ukulele também toca melodias. Vamos usar as cordas dó, mi e lá.",
1:"Brilha, brilha, estrelinha — melodia",
2:"No começo, marque as notas no braço com adesivos pequenos — é um atalho perfeitamente legítimo.",
3:{q:"Qual a vantagem de tocar melodias no instrumento?",o:["É mais fácil que acordes","Treina o ouvido e o conhecimento de onde fica cada nota","Soa mais alto","Não há vantagem"],w:"Tocar melodia conecta o ouvido ao braço — uma habilidade insubstituível."},
4:"Toque a melodia duas vezes devagar."}},

"ukulele-8":{title:"Cantar e tocar ao mesmo tempo",goal:"Combinar acompanhamento com canto",b:{
0:"É a habilidade que faz de você a pessoa convidada para tocar na fogueira. O segredo é a <b>automatização</b>: a mão precisa tocar sem que você pense nela.",
1:["Toque o acompanhamento até conseguir conversar enquanto toca.","Diga a letra no ritmo, sem cantar.","Cantarole a melodia enquanto toca.","Só agora — cante letra e melodia juntas."],
2:"Se o canto «puxar» a mão, pare de cantar, estabilize a mão e tente de novo. A mão é a âncora.",
3:{q:"Qual é a condição para cantar e tocar ao mesmo tempo?",o:["Uma boa voz","Que o acompanhamento esteja totalmente automático","Acordes complicados","Um metrônomo"],w:"Um acompanhamento automático libera a atenção para o canto."},
4:"Toque o acompanhamento e cantarole uma melodia por um minuto inteiro."}},

"ukulele-9":{title:"Peça final e um olhar adiante",goal:"Tocar uma música inteira do começo ao fim",b:{
0:"Hava Naguila — melodia tradicional (domínio público)",
1:"Os próximos passos no ukulele: acordes com pestana, a técnica do «chunk» (abafamento rítmico) e dedilhado avançado.",
2:"Encontre alguém para tocar junto. Tocar em companhia melhora o senso rítmico muito mais que qualquer estudo sozinho.",
3:{q:"Qual passo é recomendado depois de dominar os acordes abertos?",o:["Trocar de instrumento","Acordes com pestana e batidas avançadas","Parar de estudar","Aprender só partitura"],w:"A pestana abre o braço inteiro e permite tocar em qualquer tonalidade."},
4:"Grave-se tocando uma música completa."}},

/* ===================== FLAUTA DOCE ===================== */
"recorder-1":{title:"Respiração e primeira digitação",goal:"Produzir um som limpo e tocar si",b:{
0:"A flauta doce é o instrumento perfeito para começar: barata, leve e não exige força nem mãos grandes.",
1:["Segure a flauta a cerca de 45 graus do corpo.","Mão esquerda em cima — sempre! É o erro mais comum.","Apoie a ponta do bocal no lábio inferior e feche os lábios com suavidade — sem morder.","Sopre suave dizendo baixinho «tu» — essa é a articulação que começa cada nota."],
2:"Soprar forte demais dá um som estridente e agudo. A flauta precisa de <b>muito pouco</b> ar. Menos é mais.",
3:"A nota si (B)",
4:"Primeira nota: o polegar esquerdo fecha o furo de trás e o indicador esquerdo o de cima. Pronto — isso é si.",
5:{q:"Qual mão fica sempre em cima na flauta doce?",o:["A direita","A esquerda","Depende se você é canhoto","Não faz diferença"],w:"A mão esquerda fica sempre em cima — em todos os instrumentos de sopro de madeira."},
6:"Toque 10 sis longos e estáveis, de 4 segundos cada."}},

"recorder-2":{title:"Três notas — si, lá, sol",goal:"Tocar uma melodia curta",b:{
0:["<b>Si (B)</b> — polegar + dedo 1 da mão esquerda.","<b>Lá (A)</b> — acrescenta-se o dedo 2 esquerdo.","<b>Sol (G)</b> — acrescenta-se o dedo 3 esquerdo."],
1:"Exercício de três notas",
2:"Verifique se os dedos tapam os furos <b>por completo</b> — com a polpa, não com a ponta. Um furo meio aberto produz um guincho.",
3:{q:"O que acontece quando um furo não é totalmente tapado?",o:["O som fica grave demais","O som guincha ou assobia","Não acontece nada","A flauta estraga"],w:"O ar que escapa por um furo meio aberto cria um assobio."},
4:"Toque o exercício 5 vezes sem nenhum guincho."}},

"recorder-3":{title:"A primeira música",goal:"Tocar uma melodia conhecida",b:{
0:"Mary Had a Little Lamb — melodia folclórica (domínio público)",
1:"Esta música usa as notas já aprendidas mais dó e ré — entram os dedos da mão direita.",
2:"Cantarole primeiro a melodia e só depois toque no instrumento. Um ouvido que conhece a melodia guia os dedos.",
3:{q:"Qual passo é recomendado antes de tocar uma música nova?",o:["Tocá-la rápido","Cantarolá-la e conhecer a melodia","Ler as notas em voz alta","Afinar o instrumento"],w:"Um ouvido que conhece a melodia percebe o erro na hora."},
4:"Toque a música inteira duas vezes."}},

"recorder-4":{title:"Articulação com a língua",goal:"Separar as notas com limpeza",b:{
0:"Sem a língua, todas as notas se fundem num único som longo. A língua é a pontuação do seu toque.",
1:["<b>«Tu»</b> — início nítido de cada nota.","<b>«Du»</b> — início suave, para trechos cantabile.","<b>Legato</b> — língua só na primeira nota do grupo.","<b>Staccato</b> — notas curtas e separadas."],
2:"Staccato versus legato",
3:{q:"Para que serve a língua ao tocar flauta doce?",o:["Para manter o som agudo","Para separar e iniciar as notas com limpeza","Para tocar mais alto","Para afinar o instrumento"],w:"A língua define o início de cada nota — sem ela o toque soa borrado."},
4:"Toque uma escala completa uma vez em staccato e uma em legato."}},

"recorder-5":{title:"A escala completa de dó maior",goal:"Tocar uma oitava inteira",b:{
0:"Escala de dó maior",
1:"Uma escala completa exige cooperação entre as duas mãos. A dificuldade principal: a passagem das notas da mão esquerda para as da direita.",
2:"Pratique só a passagem problemática (sol→fá) vinte vezes, em vez de repetir a escala inteira sem parar.",
3:{q:"O que é melhor fazer com um trecho difícil?",o:["Repetir o trecho inteiro sem parar","Isolar as duas notas problemáticas e trabalhar só nelas","Pular o trecho","Diminuir a velocidade da música toda"],w:"O trabalho focado é muitas vezes mais eficaz que repetir o conjunto."},
4:"Toque a escala ida e volta 5 vezes com o metrônomo em 60."}},

"recorder-6":{title:"A segunda oitava",goal:"Produzir notas agudas com o polegar",b:{
0:"Para subir uma oitava, o polegar «belisca» o furo de trás — abrindo-o só um pouquinho. É a técnica do <b>sobressopro</b>.",
1:["Deslize o polegar para que a unha abra uma fresta pequena.","Aumente ligeiramente a pressão de ar.","Toque sol grave e sol agudo alternando."],
2:"Oitavas",
3:"Som estridente? A fresta está grande demais. Som grave? A fresta está fechada. A diferença é de um milímetro.",
4:{q:"Qual é a função do polegar esquerdo nas notas agudas?",o:["Fechar totalmente","Abrir uma fresta pequena","Só segurar o instrumento","Abrir totalmente"],w:"Uma fresta pequena muda o modo de vibração e sobe o som uma oitava."},
5:"Toque o exercício de oitavas 10 vezes."}},

"recorder-7":{title:"Sustenidos e bemóis",goal:"Tocar semitons",b:{
0:"Na flauta doce os semitons se obtêm com <b>digitações de garfo</b> — tapando furos não consecutivos.",
1:"O fá sustenido (F#) é a nota mais importante a aprender: é necessária em qualquer música em sol maior.",
2:"Escala de sol maior (com F#)",
3:{q:"O que é uma digitação de garfo?",o:["Tapar todos os furos","Tapar furos não consecutivos para criar um semitom","Abrir todos os furos","Uma digitação com as duas mãos"],w:"Pular um furo no meio da digitação abaixa a nota em um semitom."},
4:"Toque a escala de sol maior ida e volta."}},

"recorder-8":{title:"Expressão, respiração e fraseado",goal:"Tocar musicalmente, não mecanicamente",b:{
0:"Respirar não é só uma necessidade física — é pontuação. Respira-se no fim de uma frase musical, não no meio de uma palavra.",
1:["Marque na partitura onde vai respirar — antes de começar a tocar.","Inspire pela boca, rápido e em silêncio.","Não respire no meio de uma nota longa.","Termine a frase com um abrandamento delicado."],
2:"Toque uma frase musical como se pronunciasse uma oração: começo, ápice e final suavizado.",
3:{q:"Onde é certo respirar?",o:["A cada dois tempos","No fim de uma frase musical","Toda vez que acaba o ar","No meio de uma nota longa"],w:"Uma respiração planejada no fim da frase preserva a linha musical."},
4:"Toque uma música completa marcando antes três pontos de respiração."}},

"recorder-9":{title:"Peça final — Hino à Alegria",goal:"Tocar uma obra clássica completa",b:{
0:"Hino à Alegria — Beethoven (domínio público)",
1:"A flauta doce é uma excelente porta de entrada para outros sopros: flauta transversal, clarinete, saxofone. A respiração e a articulação passam quase iguais.",
2:{q:"Qual instrumento é considerado a continuação natural depois da flauta doce?",o:["Bateria","Flauta transversal ou clarinete","Piano","Violino"],w:"A técnica de respiração e articulação passa diretamente para os sopros de madeira."},
3:"Toque a peça do começo ao fim sem parar."}},

/* ===================== BATERIA ===================== */
"drums-1":{title:"Ritmo — a linguagem corporal da música",goal:"Manter um pulso estável",b:{
0:"Não é preciso ter bateria para começar. Uma mesa, duas mãos ou dois lápis bastam perfeitamente para as três primeiras lições.",
1:"Pulsos em semínimas — contando em quatro",
2:["Coloque o metrônomo em 72.","Bata palmas exatamente em cada pulso.","Conte em voz alta: 1-2-3-4.","Acentue o primeiro pulso."],
3:"<b>O teste:</b> se você adianta ou atrasa, ouve o metrônomo «se mexendo». Se está preciso, ele quase desaparece sob a sua palma.",
4:{q:"O que indica que você está preciso com o metrônomo?",o:["O metrônomo soa mais alto","O metrônomo quase desaparece sob o seu som","Você está tocando rápido","Não há como saber"],w:"Quando sua batida cai exatamente no clique, os dois sons se fundem."},
5:"Dois minutos de palmas precisas em 72."}},

"drums-2":{title:"O groove básico",goal:"Tocar o groove presente em 80 % das músicas",b:{
0:"O groove básico tem três componentes: <b>chimbal</b> (colcheias contínuas), <b>bumbo</b> (tempos 1 e 3) e <b>caixa</b> (tempos 2 e 4).",
1:null,
2:["Comece só com o chimbal: 1-e-2-e-3-e-4-e.","Acrescente o bumbo nos tempos 1 e 3.","Acrescente a caixa nos tempos 2 e 4.","Toque os três juntos — devagar."],
3:"Se uma mão ou um pé «derruba» os outros, baixe a velocidade em 20 %. Velocidade é resultado, não objetivo.",
4:{q:"Em quais tempos cai a caixa no groove básico?",o:["1 e 3","2 e 4","Em todos","Só no 1"],w:"A caixa em 2 e 4 é o «backbeat» — o pulso do rock e do pop."},
5:"Toque o groove por 16 compassos seguidos em 70."}},

"drums-3":{title:"Independência dos membros",goal:"Separar as mãos dos pés",b:{
0:"Independência é a capacidade de cada membro fazer algo diferente ao mesmo tempo. Isso se aprende — ninguém nasce com isso.",
1:["Toque só chimbal e caixa.","Só chimbal e bumbo.","Só bumbo e caixa.","Junte os três.","Mova o bumbo para o «4-e» — e sinta o cérebro resistir. É exatamente esse o treino."],
2:"Exercício de independência",
3:"Treine independência 5 minutos por dia — melhor que uma hora uma vez por semana. É aprendizagem motora e precisa de repetições espaçadas.",
4:{q:"Qual é a forma eficaz de desenvolver independência?",o:["Tocar rápido","Dividir em pares de membros e juntar aos poucos","Tocar músicas inteiras","Ouvir música"],w:"Dividir em pares permite ao cérebro construir o padrão passo a passo."},
5:"Treine três pares de membros, um minuto cada."}},

"drums-4":{title:"Viradas — a transição entre partes",goal:"Tocar uma virada de um compasso",b:{
0:"Uma <b>virada</b> é um trecho curto que marca a transição entre partes da música. A virada básica: quatro pares de colcheias na caixa e nos tons.",
1:"Uma virada de um compasso",
2:"A regra mais importante da virada: <b>voltar no tempo</b>. Uma virada impressionante que chega atrasada é pior que uma simples que cai certinho.",
3:{q:"O que é mais importante numa virada?",o:["Que seja rápida","Que termine exatamente a tempo para o tempo 1","Que seja longa","Que use todos os tambores"],w:"A virada serve à música — a precisão na volta importa mais que o conteúdo."},
4:"Toque 4 compassos de groove + um compasso de virada, quatro vezes."}},

"drums-5":{title:"Dinâmica e peso",goal:"Controlar a força das batidas",b:{
0:"Um bom baterista não bate forte — bate <b>certo</b>. Um bom groove tem pelo menos três níveis de volume.",
1:["Chimbal — fraco e uniforme.","Bumbo — médio, sentido na barriga.","Caixa — forte e nítida; é o que se ouve.","Tente tocar o mesmo groove a 30 % de volume e depois a 90 %."],
2:"O controle de volume vem da pegada: uma empunhadura relaxada com um «ponto de apoio» entre polegar e dedo dá uma batida livre e com rebote.",
3:{q:"Qual elemento do groove deve soar mais forte?",o:["O chimbal","A caixa","Tudo no mesmo volume","O bumbo"],w:"A caixa é o «clique» do groove e por isso se destaca."},
4:"Toque o groove em três níveis de volume diferentes."}},

"drums-6":{title:"Grooves em estilos diferentes",goal:"Conhecer quatro grooves",b:{
0:"Rock",1:"Shuffle / blues",2:"Valsa",3:"Funk (semicolcheias)",
4:"Estilo não é só um padrão — é também uma sensação. O shuffle balança, o rock é reto, o funk é nítido e picotado.",
5:{q:"O que distingue os estilos rítmicos entre si?",o:["Só a velocidade","O padrão de batidas e a sensação (reto ou balançado)","O tipo de tambores","O volume"],w:"O padrão e o «groove feeling» são o que define o estilo."},
6:"Toque cada um dos quatro grooves por 8 compassos."}},

"drums-7":{title:"Ler notação de bateria",goal:"Decifrar um esquema de groove",b:{
0:"A notação de bateria usa a mesma pauta, mas cada linha representa um tambor: chimbal em cima (X), caixa no meio, bumbo embaixo.",
1:["Linha de cima com X — chimbal.","O terceiro espaço — caixa.","O espaço de baixo — bumbo.","Conte o compasso: 1 e 2 e 3 e 4 e, e marque o que cai onde."],
2:{q:"O que significa um X na notação de bateria?",o:["Bumbo","Um prato ou o chimbal","Caixa","Uma pausa"],w:"Uma cabeça de nota em forma de X indica um instrumento de metal — chimbal, crash ou condução."},
3:"Escreva o groove básico no papel em notação."}},

"drums-8":{title:"Tocar junto com uma música",goal:"Segurar o ritmo junto com a música",b:{
0:"O baterista é o relógio da banda. Para entrar: ache o tempo 1, conte um compasso inteiro e entre.",
1:["Ouça a música e ache o backbeat (2 e 4).","Bata palmas junto por 30 segundos.","Toque o groove básico por cima da música.","Acrescente uma virada a cada 8 compassos."],
2:"Não preencha cada segundo. Os silêncios do baterista valem exatamente tanto quanto as batidas.",
3:{q:"Qual é o papel central do baterista numa banda?",o:["Ser o mais alto","Manter um ritmo estável e conduzir as transições","Tocar solos","Trocar acordes"],w:"A estabilidade do ritmo é a base em que toda a banda se apoia."},
4:"Toque junto com uma música de que goste por 3 minutos."}},

"drums-9":{title:"Encerramento e um olhar adiante",goal:"Combinar groove, viradas e dinâmica",b:{
0:"Você terminou os fundamentos: groove, independência, viradas, dinâmica e estilos.",
1:["Toque 8 compassos de groove rock.","Uma virada de um compasso.","8 compassos de shuffle.","Uma virada.","Termine com um crash no tempo 1."],
2:"A próxima etapa: os rudimentos (paradiddle, ruff, rulo duplo) — são as «escalas» do baterista.",
3:{q:"O que são rudimentos?",o:["Tipos de tambores","Padrões básicos de batida a partir dos quais tudo se constrói","Ritmos latinos","Tipos de baquetas"],w:"Os rudimentos são os tijolos da técnica de bateria."},
4:"Grave-se tocando uma sequência completa."}},

/* ===================== BAIXO ===================== */
"bass-1":{title:"Conhecendo o baixo",goal:"Tocar cordas soltas no tempo",b:{
0:"O baixo elétrico é a ponte entre a bateria e a guitarra. Quatro cordas: <b>E-A-D-G</b>, uma oitava abaixo das quatro cordas grossas de um violão.",
1:"As cordas soltas",
2:["Mão direita: indicador e médio se alternam — a «técnica de dois dedos».","O polegar apoia no captador.","Mão esquerda: um dedo por casa.","Toque cada corda solta quatro vezes."],
3:"<b>A primeira regra do baixista:</b> uma nota limpa e curta no lugar certo vale mais que dez impressionantes.",
4:{q:"Qual é a afinação padrão de um baixo de quatro cordas?",o:["G-C-E-A","E-A-D-G","E-A-D-G-B-E","D-A-D-G"],w:"E-A-D-G — as mesmas das quatro cordas grossas do violão, uma oitava abaixo."},
5:"Toque 8 tempos em cada corda solta com o metrônomo em 70."}},

"bass-2":{title:"Sua primeira linha de baixo",goal:"Tocar a fundamental de cada acorde",b:{
0:"O trabalho básico do baixista: tocar a <b>fundamental</b> do acorde que o violão toca, no primeiro tempo de cada compasso.",
1:"Linha de baixo para a sequência G-C-D",
2:["Acorde G → toque sol.","Acorde C → toque dó.","Acorde D → toque ré.","Um tempo longo por compasso e depois quatro semínimas."],
3:"Um bom baixista sabe onde cada nota está sem pensar. Pratique: «onde está o fá?» e ache-o em três lugares diferentes.",
4:{q:"O que é a fundamental?",o:["A nota mais aguda do acorde","A nota que dá nome ao acorde","A primeira nota da escala","A corda grossa"],w:"No acorde de G a fundamental é sol. É a nota básica do baixista."},
5:"Toque as fundamentais da sequência G-C-D-G, quatro tempos cada."}},

"bass-3":{title:"Ritmo e groove com a bateria",goal:"Encaixar o baixo com o bumbo",b:{
0:"A mágica de uma banda acontece quando o baixo e o bumbo tocam <b>exatamente juntos</b>. Isso se chama «lock».",
1:"Padrão de bumbo para praticar",
2:["Ouça o padrão de bumbo.","Toque uma nota exatamente em cada batida.","Não acrescente notas — apenas seja preciso.","Agora acrescente uma nota de passagem antes do compasso seguinte."],
3:"Se você toca entre os tempos e não tem certeza — não toque. Um silêncio preciso é melhor que uma nota imprecisa.",
4:{q:"Com qual instrumento o baixo deve estar mais sincronizado?",o:["O violão","O bumbo","O vocal","O piano"],w:"A dupla baixo + bumbo é a base rítmica de qualquer formação."},
5:"Toque junto com o padrão de bumbo por dois minutos."}},

"bass-4":{title:"As notas no braço",goal:"Encontrar cada nota em dois lugares",b:{
0:"Na corda mi: casa 1 = fá, casa 3 = sol, casa 5 = lá. Na corda lá: casa 2 = si, casa 3 = dó.",
1:"<b>A regra da oitava:</b> a mesma nota está também duas cordas abaixo e duas casas adiante. É o atalho mais útil do baixo.",
2:"A mesma nota em duas oitavas",
3:{q:"Onde fica a oitava de uma nota no baixo?",o:["Na mesma corda 12 casas acima, ou duas cordas abaixo e duas casas adiante","Na mesma casa da corda vizinha","Não há regra fixa","Três casas atrás"],w:"As duas estão certas, e o desenho de «duas e duas» é o mais rápido de usar."},
4:"Escolha uma nota e encontre-a em três lugares diferentes do braço."}},

"bass-5":{title:"Walking bass",goal:"Conectar acordes com notas de passagem",b:{
0:"<b>Walking bass</b> — uma linha de baixo que toca quatro notas por compasso e liga os acordes passo a passo.",
1:"Uma walking line simples",
2:["Comece na fundamental.","Toque notas do acorde (fundamental, terça, quinta).","Chegue a uma nota que esteja a um passo da fundamental seguinte.","Pouse na fundamental seguinte no tempo 1."],
3:{q:"Para que serve uma nota de passagem numa walking bass?",o:["Para preencher espaço","Para conduzir suavemente à fundamental do acorde seguinte","Para soar rápido","Para substituir a bateria"],w:"Uma nota de passagem cria expectativa e uma atração natural para o acorde seguinte."},
4:"Toque uma walking line sobre a sequência C-F-G-C."}},

"bass-6":{title:"Técnicas de mão direita",goal:"Conhecer dedos, palheta e slap",b:{
0:["<b>Com os dedos:</b> o som mais quente e comum.","<b>Com palheta:</b> som nítido e cortante, bom para rock e punk.","<b>Slap:</b> o polegar bate na corda grossa e o dedo «puxa» a fina — o som funk característico."],
1:"Padrão de slap básico",
2:"No slap o polegar gira em torno de um eixo — ele não «espeta». O rebote faz parte do movimento.",
3:{q:"O que é a técnica de slap?",o:["Tocar com palheta","Uma batida de polegar e um puxão de dedo","Tocar com as duas mãos","Abafar as cordas"],w:"A combinação de batida do polegar e puxão do dedo cria o som percussivo."},
4:"Toque oito compassos com cada uma das técnicas."}},

"bass-7":{title:"Abafamento e controle de ruído",goal:"Tocar limpo, sem cordas soando",b:{
0:"O problema número um no baixo não são notas erradas — é o <b>ruído</b>: cordas que continuam vibrando.",
1:["O polegar da mão direita apoia na corda grossa e a abafa.","Os dedos da mão esquerda que não tocam encostam de leve nas cordas vizinhas.","Depois de cada nota, pense em como você a <b>interrompe</b>, não só em como a começa.","Toque uma nota, abafe-a por completo e só então toque a seguinte."],
2:{q:"Qual é o problema mais comum ao tocar baixo?",o:["Notas erradas","Ruído de cordas não abafadas","Andamento lento","Cordas finas"],w:"O controle de ruído é a diferença entre um amador e um profissional."},
3:"Toque nota-silêncio-nota-silêncio por um minuto."}},

"bass-8":{title:"Uma linha de baixo para uma música inteira",goal:"Construir uma linha de baixo própria",b:{
0:"Uma boa linha de baixo se constrói em três etapas: só fundamentais → fundamentais no ritmo → acrescentar notas de passagem e variação.",
1:"Riff de blues (exercício original)",
2:"Ouça os baixistas das músicas de que você gosta. Repare em como tocam pouco — e como soa certo.",
3:{q:"Qual é a ordem correta para construir uma linha de baixo?",o:["Improvisar de cara","Fundamentais → ritmo → notas de passagem","Copiar um solo","Começar pela nota mais aguda"],w:"A construção gradual mantém a linha estável e a serviço da música."},
4:"Construa uma linha de baixo para uma música que você conhece, nas três etapas."}},

"bass-9":{title:"Encerramento e um olhar adiante",goal:"Tocar com uma banda",b:{
0:"Você terminou os fundamentos. Um baixista com tempo estável, som limpo e compreensão harmônica é procurado em qualquer banda.",
1:["Estude com metrônomo todos os dias, nem que sejam 5 minutos.","Grave-se — o ouvido capta o que a mão não sente.","Toque com outras pessoas o quanto antes.","Aprenda a escala maior e a menor natural em todo o braço."],
2:{q:"Qual é a qualidade mais importante num baixista?",o:["Velocidade","Tempo estável e som limpo","Conhecer partitura","Equipamento caro"],w:"A estabilidade é o que faz a banda inteira soar bem."},
3:"Toque uma música completa do começo ao fim com metrônomo."}}

});

/* ---- os quatro instrumentos novos ---- */
I18N.registerLessons("pt", {

"violin-1":{title:"Como segurar e as cordas soltas",goal:"Produzir um som limpo nas quatro cordas",b:{
0:"O violino é o instrumento em que <b>o ouvido guia o dedo</b>. Não há trastes, por isso cada nota se constrói ouvindo — e é exatamente isso que faz dele o melhor professor para o ouvido.",
1:"Quatro cordas, da mais grossa à mais fina: <b>sol, ré, lá, mi</b>. Entre cada par há uma quinta.",
3:["Apoie o violino na clavícula, com o queixo na queixeira.","A mão esquerda segura o braço com leveza — não aperta.","O arco pousa na corda a meio caminho entre o cavalete e a escala.","Puxe o arco devagar e com pressão uniforme. Um som limpo vale mais que um som forte."],
4:"Um assobio? Uma de três coisas: pressão desigual, arco longe demais do cavalete, ou velocidade a mudar. Vá mais devagar.",
5:{q:"Como se afinam as cordas do violino?",o:["Em quartas","Em quintas","Em oitavas","Em terças"],w:"Sol-ré-lá-mi — uma quinta entre cada par de cordas vizinhas."},
6:"Toque cada corda solta oito vezes com arco inteiro, sem assobios."}},

"violin-2":{title:"O primeiro dedo",goal:"Tocar quatro notas novas",b:{
0:"O primeiro dedo pousa a <b>um tom inteiro</b> da corda solta. É o ponto de referência de toda a mão.",
2:"Cole um pedacinho de fita onde o primeiro dedo cai. Não é batota — é assim que todos os violinistas do mundo aprendem no primeiro ano.",
3:"Corda solta e primeiro dedo",
4:{q:"Qual é a distância entre a corda solta e o primeiro dedo?",o:["Um semitom","Um tom inteiro","Um tom e meio","Dois tons"],w:"Um tom inteiro — e é a primeira distância que o ouvido aprende."},
5:"Toque o exercício devagar e confira cada nota com o afinador da aplicação."}},

"violin-3":{title:"Uma primeira melodia",goal:"Tocar uma peça inteira em duas cordas",b:{
0:"Com as cordas soltas e o primeiro dedo já dá para tocar uma melodia de verdade.",
2:"Exercício em duas cordas",
3:"<b>A regra do primeiro ano:</b> devagar e limpo vence sempre rápido e confuso.",
4:{q:"O que importa mais nesta fase?",o:["Tocar rápido para avançar","Tocar devagar e ouvir cada nota","Saltar as notas difíceis","Tocar o mais alto possível"],w:"No violino, qualquer imprecisão ouve-se de imediato. Abrandar é o atalho."},
5:"Toque a melodia cinco vezes, um pouco mais rápido de cada vez."}},

"violin-4":{title:"Três dedos — a tua primeira escala",goal:"Tocar a escala de ré maior em duas cordas",b:{
0:"No violino a escala não se constrói com trastes, mas com um <b>padrão fixo de dedos</b>. Assim que a mão o aprende, ele repete-se em qualquer corda.",
1:"Na corda ré: dedo 1 = mi, dedo 2 = fá sustenido, dedo 3 = sol. Repara que os dedos 2 e 3 <b>se tocam</b> — é o sinal de que o padrão está certo.",
3:"Escala de ré maior",
4:"Os dedos 2 e 3 ficam juntos numa escala maior. Se abrir um espaço entre eles, o fá sustenido sai baixo.",
5:{q:"O que caracteriza a posição dos dedos 2 e 3 em maior?",o:["Um grande espaço entre eles","Tocam-se um no outro","O dedo 3 não se usa","Não há regra fixa"],w:"A proximidade deles é o semitom entre o terceiro e o quarto graus."},
6:"Toque a escala nos dois sentidos dez vezes, devagar, conferindo cada nota no afinador."}},

"violin-5":{title:"A distribuição do arco",goal:"Controlar a duração e a força do som",b:{
0:"O arco é a <b>respiração</b> do violino. Uma nota longa pede arco lento; uma curta, pouco arco — e a pressão mantém-se constante.",
1:["Marque três zonas: talão, meio e ponta.","Toque uma semibreve com arco inteiro, do talão à ponta, em quatro segundos.","Toque quatro semínimas nesse mesmo arco — cada uma um quarto do percurso.","Agora toque colcheias usando só o meio do arco."],
2:"Distribuição do arco",
3:"O som enfraquece no fim do arco? A pressão desce junto com o braço. Mantenha-a uniforme até à ponta.",
4:{q:"O que determina a duração de uma nota no violino?",o:["A pressão do dedo","A velocidade do arco","Como se segura o instrumento","A espessura da corda"],w:"A velocidade do arco define a duração; a pressão define o volume."},
5:"Toque uma escala inteira com arco completo por nota e depois com meio arco."}},

"violin-6":{title:"Segunda corda e mudanças",goal:"Passar entre cordas sem ruído",b:{
0:"A passagem entre cordas é onde se ouve a diferença entre um principiante e um músico. O segredo: <b>o braço começa a mover-se antes de a nota mudar</b>.",
2:"Exercício de mudanças",
3:"Se ouvir um som duplo durante a passagem, o arco tocou duas cordas. O que deve mudar é o ângulo, não a pressão.",
4:{q:"O que provoca um som duplo ao mudar de corda?",o:["Pressão a mais","O arco toca duas cordas","O instrumento está desafinado","O dedo está mal colocado"],w:"É o ângulo do arco que separa as cordas."},
5:"Toque o exercício dez vezes, completamente limpo."}},

"violin-7":{title:"Um primeiro vibrato",goal:"Conhecer o movimento do vibrato",b:{
0:"O vibrato é um <b>pequeno balanço do dedo</b> que aquece o som. Ensina-se mais tarde do que se pensa — e de propósito: ele disfarça a imprecisão, por isso primeiro aprende-se a tocar limpo sem ele.",
1:["Coloque o dedo 2 na corda lá, sem arco.","Balance a mão para a frente e para trás a partir do pulso, não do dedo.","O dedo fica no lugar — só a altura varia ligeiramente.","Acrescente o arco só quando o movimento estiver fluido."],
2:"Um vibrato rápido e estreito soa a tremor. Lento e largo, soa a canto. Comece devagar.",
3:{q:"De onde vem o movimento do vibrato?",o:["Do dedo","Do pulso","Só do cotovelo","Do ombro"],w:"O movimento nasce no pulso; o dedo apenas o acompanha."},
4:"Pratique o movimento um minuto sem arco e depois um minuto com arco."}},

"violin-8":{title:"Uma melodia completa",goal:"Tocar uma peça conhecida do início ao fim",b:{
0:"Agora junta-se tudo: o padrão de dedos, a distribuição do arco e as mudanças de corda.",
1:"Melodia para duas cordas",
2:"Toque primeiro sem arco — em pizzicato — para confirmar que os dedos estão no sítio. Depois acrescente o arco.",
3:{q:"O que convém verificar antes de acrescentar o arco?",o:["O volume","Que os dedos estão bem colocados","O andamento","A posição da cabeça"],w:"O pizzicato isola a mão esquerda e revela as imprecisões de imediato."},
4:"Toque a melodia cinco vezes — duas em pizzicato e três com arco."}},

"violin-9":{title:"Balanço e próximos passos",goal:"Tocar com confiança e saber para onde ir",b:{
0:"Terminou os fundamentos: a postura, as cordas soltas, o padrão de dedos, a distribuição do arco e as mudanças. Tudo o resto assenta nisto.",
1:"O que vem a seguir: <b>a segunda posição</b> (mover toda a mão pelo braço), <b>tocar em duas cordas ao mesmo tempo</b> e <b>ler pauta</b> enquanto toca.",
2:"Peça final",
3:"<b>O erro clássico do segundo ano:</b> acelerar antes de o som estar limpo. Toque tudo com metrónomo lento — e ultrapassará quem se apressou.",
4:{q:"Qual é o passo natural seguinte no violino?",o:["Tocar mais depressa","A segunda posição e a leitura","Mudar de instrumento","Dispensar o arco"],w:"A segunda posição abre o resto do braço, e a leitura abre o repertório."},
5:"Toque a peça final e grave-se. Ouvir-se depois é o professor mais honesto."}},

"harmonica-1":{title:"Soprar e aspirar",goal:"Produzir um som limpo a partir de um só furo",b:{
0:"A gaita é o único instrumento em que <b>soprar e aspirar produzem ambos um som</b> — e dois sons diferentes do mesmo furo.",
1:"Uma gaita em dó tem dez furos e vinte palhetas. O quarto furo é o ponto de partida de quase todas as melodias.",
3:["Segure a gaita entre o polegar e o indicador, com os números para cima.","Arredonde os lábios como se dissesse «u».","Sopre suavemente no furo quatro — sai dó.","Agora aspire do mesmo furo — sai ré."],
4:"Saem várias notas ao mesmo tempo? A boca está aberta demais. Aperte os lábios até restar uma só nota limpa.",
5:{q:"O que distingue a gaita dos outros instrumentos de sopro?",o:["Não tem notas agudas","Soprar e aspirar produzem ambos som","Tem de se afinar sempre","É preciso carregar em botões"],w:"Cada furo tem duas palhetas — uma para soprar e outra para aspirar."},
6:"Alterne soprar e aspirar no furo 4, vinte vezes, com som limpo."}},

"harmonica-2":{title:"Quatro furos — a tua primeira melodia",goal:"Tocar uma melodia conhecida",b:{
0:"Os furos 4 a 7 contêm uma escala completa de dó maior. É lá que vive quase toda a canção popular.",
2:"Repare na seta por cima do diagrama: para cima é soprar, para baixo é aspirar. É tudo o que precisa de decorar.",
3:"A escala na gaita",
4:{q:"Em que furos está a escala completa de dó maior?",o:["De 1 a 4","De 4 a 7","De 7 a 10","Em todos"],w:"Só de 4 a 7 a escala fica completa sem bending."},
5:"Toque a escala nos dois sentidos dez vezes."}},

"harmonica-3":{title:"A tua primeira canção",goal:"Tocar uma melodia inteira de cor",b:{
0:"Agora junta-se tudo. Esta melodia usa apenas os furos 4 a 6.",
2:"Melodia para quatro furos",
3:"Experimente tocar sem olhar para os números. Na gaita, o ouvido encontra o furo mais depressa que o olho.",
4:{q:"Qual é a melhor forma de aprender uma melodia na gaita?",o:["Decorar os números dos furos","Ouvir e procurar de ouvido","Contar as respirações","Ler pauta"],w:"A gaita foi feita para tocar de ouvido — é essa a sua força."},
5:"Toque a melodia três vezes de olhos fechados."}},

"harmonica-4":{title:"Tocar um só furo",goal:"Produzir uma nota limpa sem vizinhas",b:{
0:"Até aqui talvez soassem várias notas juntas. Agora vai aprender a tirar <b>apenas uma</b> — e é isso que transforma ruído em melodia.",
1:["Meta a gaita mais fundo entre os lábios, como se estivesse a beber.","A língua fica em baixo, relaxada.","Aperte a abertura dos lábios até soar uma única nota.","Confirme: sopre no furo 4 — se ouvir um acorde, os lábios estão largos demais."],
3:"Um segundo método, o <b>bloqueio com a língua</b>: cubra três furos com a boca e bloqueie dois com a língua. Fica um aberto.",
4:{q:"Porque soam várias notas ao mesmo tempo?",o:["A gaita está avariada","A abertura dos lábios é larga demais","Está a soprar com força a mais","Os furos estão entupidos"],w:"Uma boca larga cobre vários furos de uma vez."},
5:"Toque os furos 4, 5 e 6 a soprar — cada um em separado e limpo, vinte vezes."}},

"harmonica-5":{title:"A segunda oitava",goal:"Alargar o registo aos furos 1 a 7",b:{
0:"Os furos graves (1–3) dão os sons profundos, e os agudos (7–10) os mais penetrantes. A maioria das melodias vive no meio.",
2:"Repare numa curiosidade: a partir do furo 7 <b>o aspirar é mais grave que o soprar</b> — ao contrário dos furos graves. É uma propriedade da afinação, não uma avaria.",
3:"Registo completo",
4:{q:"O que muda a partir do furo 7?",o:["Nada","O aspirar passa a ser mais grave que o soprar","Não se pode aspirar","O som fica mais fraco"],w:"É uma inversão própria da afinação Richter."},
5:"Toque todos os sopros do furo 1 ao 10 e de volta."}},

"harmonica-6":{title:"Ritmo e respiração",goal:"Tocar a tempo sem ficar sem ar",b:{
0:"Na gaita a respiração é ao mesmo tempo o som e o combustível. Toque demasiado tempo numa direção e fica sem ar.",
1:"Alternar soprar e aspirar",
2:"<b>A regra:</b> se a melodia pedir três sopros seguidos, procure um sítio para mudar de direção. Quase sempre a mesma nota existe noutro furo.",
3:"Exercício de respiração",
4:{q:"O que fazer quando fica sem ar a meio de uma frase?",o:["Soprar com mais força","Procurar um sítio para mudar de direção","Parar de tocar","Tocar mais depressa"],w:"Mudar de direção é a forma de a gaita respirar."},
5:"Toque o exercício dois minutos seguidos sem ficar ofegante."}},

"harmonica-7":{title:"Acordes e trémolo",goal:"Usar vários furos em conjunto de propósito",b:{
0:"Até agora lutámos contra as notas vizinhas. Agora <b>usamo-las de propósito</b>: vários furos juntos dão um acorde completo.",
1:"Soprar nos furos 1–4 dá um acorde de dó maior. Aspirar nos furos 1–4 dá um acorde de sol.",
2:"<b>Trémolo:</b> agite a mão que segura a gaita à frente da boca. O som ondula e lembra um comboio.",
3:"Acompanhamento em acordes",
4:{q:"Que acorde sai ao soprar nos furos 1 a 4?",o:["Sol maior","Dó maior","Lá menor","Ré maior"],w:"Os sopros são feitos das notas do acorde de dó — dó, mi e sol."},
5:"Toque um acompanhamento em acordes numa canção que conheça, dois minutos."}},

"harmonica-8":{title:"Uma canção inteira",goal:"Tocar uma melodia conhecida do princípio ao fim",b:{
0:"Agora junta-se tudo: furo único, ritmo e respiração planeada.",
2:"Melodia completa",
3:"Marque antecipadamente onde sopra e onde aspira. Planear evita ficar sem fôlego.",
4:{q:"O que ajuda a não ficar sem fôlego?",o:["Tocar baixinho","Planear antecipadamente os sopros e as aspirações","Tocar depressa","Encurtar a canção"],w:"Planear a direção do ar é a competência central da gaita."},
5:"Toque a melodia cinco vezes seguidas sem parar."}},

"harmonica-9":{title:"Balanço e próximos passos",goal:"Saber o que aprendeu e para onde ir",b:{
0:"Terminou os fundamentos: soprar e aspirar, furo único, registo completo, ritmo, acordes e uma canção inteira.",
1:"O que vem a seguir: o <b>bending</b> — alterar a altura do som com a língua, o que permite tocar as notas que não estão na afinação. É isso que dá à gaita a sua cor de blues.",
2:"Peça final",
3:"O bending leva meses, não dias. Não o treine antes de as suas notas simples estarem perfeitamente limpas.",
4:{q:"O que torna o bending possível?",o:["Outra gaita","Mudar a forma da boca e da língua","Soprar com força","Trocar as palhetas"],w:"A forma da cavidade bucal altera a altura do som."},
5:"Toque a peça final e grave-se."}},

"glock-1":{title:"A primeira pancada",goal:"Produzir um som limpo e perceber a disposição",b:{
0:"O glockenspiel é o instrumento melódico mais fácil para começar: <b>nada para afinar, sem dedilhado e sem sopro</b>. Bate-se — e sai a nota certa.",
1:"As lâminas estão dispostas exatamente como as teclas de um piano: uma fila longa de brancas e, por cima, grupos de duas e de três.",
2:"Bata na lâmina marcada — este é o dó",
3:["Segure a baqueta com leveza, entre o polegar e o indicador.","Bata no centro da lâmina — não na ponta.","Levante a baqueta logo após a pancada. Uma baqueta pousada abafa o som.","Uma pancada leve chega. O instrumento faz o trabalho."],
4:"Som abafado? A baqueta ficou na lâmina. Pense em ressaltar, não em carregar.",
5:{q:"Onde se bate na lâmina?",o:["Na ponta","No centro","Perto do parafuso","É indiferente"],w:"O centro dá o som mais cheio. As pontas soam abafadas."},
6:"Bata em cada lâmina branca uma vez, do grave ao agudo, com som limpo."}},

"glock-2":{title:"A escala e a tua primeira melodia",goal:"Tocar uma melodia conhecida",b:{
0:"A escala de dó maior são simplesmente todas as lâminas brancas seguidas. É tudo o que é preciso para a primeira melodia.",
1:"Escala de dó maior",
2:"Primeira melodia",
3:"<b>Alternar as mãos:</b> direita-esquerda-direita-esquerda. Duplica a velocidade sem esforço adicional.",
4:{q:"Qual é a vantagem de alternar as mãos?",o:["Um som mais forte","Tocar mais depressa sem esforço","As lâminas gastam-se menos","Não há vantagem"],w:"Uma só mão tem de voltar atrás; duas alternam sem interrupção."},
5:"Toque a melodia alternando as mãos, cinco vezes."}},

"glock-3":{title:"Ritmo e dinâmica",goal:"Tocar com intensidades diferentes e a tempo",b:{
0:"No glockenspiel o som é curto, por isso <b>o tempo e a intensidade</b> são toda a expressão de que dispõe. É isso que transforma uma execução banal numa marcante.",
1:"Ritmo básico",
2:"Experimente tocar a mesma melodia uma vez com força e outra com suavidade. A diferença é maior do que parece.",
3:"A mesma melodia, outro ritmo",
4:{q:"O que cria expressão no glockenspiel?",o:["A duração das notas","A intensidade e o tempo","A afinação das lâminas","O número de baquetas"],w:"O som é curto e fixo: as suas ferramentas são o volume e o rigor no tempo."},
5:"Toque a melodia três vezes: suave, média e forte."}},

"glock-4":{title:"Duas mãos e saltos",goal:"Tocar uma passagem que se desloca entre regiões",b:{
0:"No glockenspiel a mão não fica parada. <b>O olho guia — a mão segue</b>, e isso aprende-se em separado.",
1:"Três pontos de referência — dó, sol e dó agudo",
2:["Localize os três pontos de apoio no instrumento.","Bata em dó e depois em sol, sem olhar para a baqueta.","Acrescente o dó agudo.","Agora toque os três seguidos com metrónomo a 60."],
3:"Olhe para a lâmina <b>seguinte</b> enquanto bate na atual. É o segredo de qualquer percussionista de lâminas.",
4:{q:"Para onde se olha enquanto se toca?",o:["Para a baqueta","Para a lâmina seguinte","Só para a pauta","É indiferente"],w:"O olhar vai à frente da mão, tal como na leitura."},
5:"Toque dó-sol-dó vinte vezes sem falhar."}},

"glock-5":{title:"As lâminas superiores",goal:"Tocar numa escala com sustenido",b:{
0:"As lâminas superiores são os semitons — exatamente como as teclas pretas do piano, e nos mesmos grupos de duas e de três.",
1:"Escala de sol maior — atenção ao fá sustenido",
2:"As lâminas superiores são mais estreitas. Aponte ao centro, senão a baqueta escorrega.",
3:{q:"Como estão dispostas as lâminas superiores?",o:["Numa fila uniforme","Em grupos de duas e de três","Ao acaso","Não há lâminas superiores"],w:"Exatamente como as teclas pretas de um piano."},
4:"Toque a escala de sol maior nos dois sentidos, cinco vezes."}},

"glock-6":{title:"Ritmo mais complexo",goal:"Tocar colcheias e notas pontuadas",b:{
0:"O som do glockenspiel é curto, por isso o <b>rigor rítmico</b> ouve-se logo. Aqui aprende-se a dividir a pulsação.",
1:"Colcheias",
2:"Melodia em colcheias",
3:"Conte em voz alta: «um-e-dois-e». Contar em voz alta é mais rigoroso do que contar de cabeça.",
4:{q:"O que ajuda ao rigor rítmico?",o:["Tocar forte","Contar em voz alta","Tocar depressa","Olhar para as mãos"],w:"Contar em voz alta liga o corpo ao tempo."},
5:"Toque a melodia com metrónomo a 70 e depois a 85."}},

"glock-7":{title:"Duas vozes",goal:"Tocar melodia e acompanhamento em conjunto",b:{
0:"Duas mãos são duas vozes. Uma mão toca a melodia, a outra acrescenta uma nota de apoio.",
1:"Acorde de dó — as três notas juntas",
2:"Melodia com apoio",
3:"Comece com a segunda mão a bater só no primeiro tempo de cada compasso. Já chega para soar cheio.",
4:{q:"Qual é a forma mais simples de acrescentar uma segunda voz?",o:["Tocar tudo duas vezes","Uma nota de apoio no primeiro tempo","Tocar mais depressa","Acrescentar uma terceira baqueta"],w:"Um único apoio por compasso já cria a sensação de acompanhamento."},
5:"Toque a melodia com apoio, cinco vezes."}},

"glock-8":{title:"Uma peça para apresentar",goal:"Tocar uma peça completa com segurança",b:{
0:"Agora junta-se tudo: saltos, lâminas superiores, ritmo e duas vozes.",
1:"Peça para apresentar",
2:"Trabalhe a peça em três secções separadas e só depois as junte. É assim que estudam os profissionais.",
3:{q:"Como se aprende uma peça longa?",o:["Tocando-a vezes sem conta","Dividindo em secções e depois juntando","Tocando só o início","Acelerando aos poucos"],w:"Dividir poupa tempo e impede que os erros se fixem."},
4:"Toque a peça três vezes seguidas sem parar."}},

"glock-9":{title:"Balanço e próximos passos",goal:"Saber o que aprendeu e para onde ir",b:{
0:"Terminou: a pancada limpa, a escala, os saltos, as lâminas superiores, o ritmo e as duas vozes.",
1:"O que vem a seguir: o <b>xilofone e a marimba</b> (lâminas de madeira, som mais quente), <b>quatro baquetas</b> em duas mãos e <b>ler pauta</b> enquanto toca.",
2:"Peça final",
3:"O glockenspiel é uma excelente porta de entrada para toda a percussão melódica. A competência transfere-se quase por inteiro.",
4:{q:"Qual é a diferença entre glockenspiel e xilofone?",o:["O tamanho","Lâminas de metal contra lâminas de madeira","O número de lâminas","A afinação"],w:"O metal dá um som brilhante e longo; a madeira, quente e curto."},
5:"Toque a peça final e grave-se."}},

"mandolin-1":{title:"Primeiro contacto e cordas soltas",goal:"Produzir um som limpo e conhecer a afinação",b:{
0:"O bandolim é afinado <b>exatamente como um violino</b> — sol, ré, lá, mi — mas tem trastes. Cada nota tem um lugar fixo e nada se procura de ouvido.",
2:["Segure a palheta entre o polegar e o indicador, só pela ponta.","Toque para baixo e para cima alternadamente — é o movimento básico.","Mão esquerda: pressione logo atrás do traste, não em cima.","Toque cada par de cordas soltas quatro vezes."],
3:"Cada nota tem duas cordas lado a lado. É isso que dá ao bandolim o seu som tilintante.",
4:{q:"Em que difere o bandolim do violino?",o:["Na afinação","Em ter trastes","No número de cordas","Só no tamanho"],w:"A afinação é idêntica; a diferença são os trastes, e são eles que facilitam o início."},
5:"Toque cada corda solta oito vezes, para baixo e para cima."}},

"mandolin-2":{title:"Primeiras notas no braço",goal:"Tocar a tua primeira escala",b:{
0:"Graças aos trastes, encontrar uma nota no bandolim é uma questão de contar — não de ouvir.",
2:"Cinco notas",
3:"Um dedo por traste — é a regra que lhe poupa anos de correções.",
4:{q:"Como se encontra uma nota no bandolim?",o:["Só de ouvido","Pelo número do traste","Pela cor da corda","Não é possível ter a certeza"],w:"Os trastes fixam a altura com precisão."},
5:"Toque as cinco notas nos dois sentidos, dez vezes."}},

"mandolin-3":{title:"Uma primeira melodia",goal:"Tocar uma peça inteira",b:{
0:"Agora junta-se tudo: cordas soltas, notas no braço e palheta regular.",
2:"Melodia para bandolim",
3:"<b>Trémolo:</b> repetição rápida da palheta na mesma nota. É o som que todos reconhecem como bandolim — mas só depois de a palheta normal estar estável.",
4:{q:"O que é o trémolo?",o:["Uma mudança rápida de acordes","Repetição rápida da palheta na mesma nota","Tocar em duas cordas","Abrandar no final"],w:"É a técnica que identifica o bandolim."},
5:"Toque a melodia cinco vezes com palheta regular."}},

"mandolin-4":{title:"O teu primeiro acorde",goal:"Tocar um acorde de sol e mudar para ele",b:{
0:"No bandolim um acorde são <b>apenas dois dedos</b> na maioria dos casos — bem menos do que uma guitarra exige.",
2:["Dedo 1 na corda lá, traste 2.","Dedo 2 na corda mi, traste 3.","As outras duas cordas ficam soltas.","Toque para baixo sobre os quatro pares."],
3:"Pressione logo atrás do traste, não em cima. É aí que é preciso menos força.",
4:{q:"Quantos dedos são precisos para um acorde básico no bandolim?",o:["Quatro","Dois","Três","Nenhum"],w:"Dois chegam para a maioria dos acordes soltos."},
5:"Alterne entre o acorde de sol e as cordas soltas, vinte vezes."}},

"mandolin-5":{title:"Dois acordes e uma canção",goal:"Acompanhar uma canção inteira com dois acordes",b:{
0:"Com dois acordes já se acompanham centenas de canções. A mudança entre eles é todo o trabalho.",
1:"Palheta para baixo e para cima",
2:"<b>A regra da mudança:</b> levante os dedos um instante antes do tempo, não em cima dele. Assim não fica um buraco no ritmo.",
3:"Exercício de acompanhamento",
4:{q:"Quando se levantam os dedos ao mudar de acorde?",o:["Exatamente no tempo","Um instante antes do tempo","Depois do tempo","É indiferente"],w:"Levantar cedo mantém a continuidade do ritmo."},
5:"Alterne os dois acordes durante dois minutos sem parar."}},

"mandolin-6":{title:"O trémolo",goal:"Produzir um som sustentado com palheta repetida",b:{
0:"O bandolim não tem som longo — apaga-se logo. O <b>trémolo</b> é a solução: uma repetição rápida que cria a ilusão de um som sustentado.",
1:["Segure a palheta muito solta — é essa a chave.","Mova-se a partir do pulso, não do cotovelo.","Comece devagar e regular, e só depois acelere.","Toque uma nota em trémolo durante quatro segundos."],
2:"Uma pega tensa dá um trémolo aos solavancos. Quanto mais macia a pega, mais liso o som.",
3:"Nota longa em trémolo",
4:{q:"O que mais importa no trémolo?",o:["A velocidade","Uma pega descontraída","Muita pressão","Uma palheta grossa"],w:"O relaxamento permite a velocidade; a tensão impede-a."},
5:"Pratique trémolo numa só nota, um minuto por corda."}},

"mandolin-7":{title:"Escalas em duas oitavas",goal:"Alargar o registo ao longo do braço",b:{
0:"Graças à afinação por quintas, o mesmo padrão de dedos repete-se em cada par de cordas. Aprende-se uma vez — e toca-se em todo o lado.",
2:"Escala de sol em duas oitavas",
3:"O padrão aprendido na corda sol funciona exatamente igual na corda ré. É essa a grande poupança da afinação por quintas.",
4:{q:"Qual é a vantagem de afinar por quintas?",o:["Um som mais forte","O mesmo padrão repete-se em cada par de cordas","É mais fácil de afinar","Menos cordas"],w:"O padrão mantém-se, por isso só é preciso aprendê-lo uma vez."},
5:"Toque a escala em duas oitavas, dez vezes."}},

"mandolin-8":{title:"Melodia com acompanhamento",goal:"Tocar uma canção inteira e intercalar acordes",b:{
0:"Agora combina-se tudo: melodia, acordes e trémolo na mesma peça.",
1:"Peça combinada",
2:"Toque primeiro só a melodia, depois só os acordes, e só então combine. Combinar cedo demais estraga ambos.",
3:{q:"Como se combinam melodia e acompanhamento?",o:["Tocando-os juntos desde o início","Aprendendo cada um em separado e depois combinando","Abdicando de um deles","Tocando muito devagar"],w:"Separar primeiro e combinar depois — é o caminho rápido."},
4:"Toque a peça combinada cinco vezes."}},

"mandolin-9":{title:"Balanço e próximos passos",goal:"Saber o que aprendeu e para onde ir",b:{
0:"Terminou: cordas soltas, notas no braço, acordes, trémolo e escalas em duas oitavas.",
1:"O que vem a seguir: o <b>estilo bluegrass</b> (palheta rápida e precisa), os <b>acordes fechados</b> que se deslocam pelo braço e a <b>improvisação</b> sobre as escalas aprendidas.",
2:"Peça final",
3:"O bandolim partilha a afinação com o violino — tudo o que aprendeu aqui transfere-se quase por inteiro se algum dia quiser experimentá-lo.",
4:{q:"Que instrumento partilha a afinação do bandolim?",o:["A guitarra","O violino","O baixo","O cavaquinho"],w:"Ambos são afinados sol-ré-lá-mi."},
5:"Toque a peça final e grave-se."}}

});
